import{z}from'zod';import{createAdminSupabaseClient,isSupabaseAdminConfigured}from'@/src/lib/supabase';import{resolveExternalApiKey}from'@/src/lib/security/webhookAuth';import{createHash}from'crypto';export const runtime='nodejs';const s=z.object({jobOpeningId:z.string().uuid(),firstName:z.string().min(1),lastName:z.string().min(1),email:z.string().email(),source:z.string().max(120).optional(),tags:z.array(z.string()).optional()});export async function POST(r:Request){const key=await resolveExternalApiKey(r,'leads:write');if(!key.success)return Response.json({success:false,error:key.error},{status:401});if(!isSupabaseAdminConfigured)return Response.json({success:false,error:'Server unavailable.'},{status:503});try{const p=s.parse(await r.json());const db=createAdminSupabaseClient();const org=key.data.organization_id;const{data:candidate,error}=await db.from('candidates').upsert({organization_id:org,first_name:p.firstName,last_name:p.lastName,email:p.email,source:p.source||'external_webhook',tags:p.tags||[]},{onConflict:'organization_id,email'}).select().single();if(error)return Response.json({success:false,error:error.message},{status:400});const{data:application,error:appError}=await db.from('applications').upsert({organization_id:org,candidate_id:candidate.id,job_opening_id:p.jobOpeningId,stage:'applied',source:p.source||'external_webhook',stage_changed_at:new Date().toISOString()},{onConflict:'candidate_id,job_opening_id'}).select().single();await db.from('external_webhook_logs').insert({organization_id:org,direction:'inbound',event_type:'candidate.lead',endpoint:'inbound-lead',status_code:appError?400:202,payload_hash:createHash('sha256').update(JSON.stringify(p)).digest('hex'),error_message:appError?.message||null});return appError?Response.json({success:false,error:appError.message},{status:400}):Response.json({success:true,data:{candidateId:candidate.id,applicationId:application.id}},{status:202})}catch(e){return Response.json({success:false,error:e instanceof z.ZodError?e.issues.map(i=>i.message).join(' '):'Invalid lead payload.'},{status:400})}}